# Mr Lee - one-file installer: history question-by-question review.
# Windows PowerShell 5.1 / PowerShell 7. Creates backups; aborts without writing if a file is incompatible.
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$utf8 = New-Object System.Text.UTF8Encoding($false)
function D([string]$value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($value)) }
function MustReplace([string]$content,[string]$old,[string]$new,[string]$name) {
    if (-not $content.Contains($old)) { throw "Cannot find expected code in $name. No files were changed. Send this HTML/JS file for a custom fix." }
    return $content.Replace($old,$new)
}
$required = @('mrlee-online.js','learning-tracker.js','learning-history.js')
foreach ($item in $required) {
    if (-not (Test-Path -LiteralPath (Join-Path $root $item))) { throw "Missing $item in the website folder. No files were changed." }
}
$onlinePath=Join-Path $root 'mrlee-online.js'
$trackerPath=Join-Path $root 'learning-tracker.js'
$historyPath=Join-Path $root 'learning-history.js'
$online=[System.IO.File]::ReadAllText($onlinePath,[System.Text.Encoding]::UTF8)
$tracker=[System.IO.File]::ReadAllText($trackerPath,[System.Text.Encoding]::UTF8)
$history=[System.IO.File]::ReadAllText($historyPath,[System.Text.Encoding]::UTF8)
# Validate all three patches in memory before any backup/write.
if (-not $online.Contains('mrlee-review-v1')) {
  $online=MustReplace $online (D 'bGV2ZWw6c2VsZWN0ZWRMZXZlbCxzY29yZSx0b3RhbCxkdXJhdGlvblNlY29uZHM=') (D '') 'mrlee-online.js'
}
if (-not $online.Contains('mrlee-review-deep-link-v1')) {
  $online=MustReplace $online (D 'dHJ5IHsgaWYgKGxvY2FsU3RvcmFnZS5nZXRJdGVtKCdtcmxlZS1vbmxpbmUtbGV2ZWwnKSA9PT0gJ3NjMicpIHNlbGVjdGVkTGV2ZWwgPSAnc2MyJzsgfSBjYXRjaCB7fQ==') (D '') 'mrlee-online.js deep link'
}
if (-not $online.Contains('mrlee-review-highlight-v1')) {
  $needle='makeBatches();'
  $pos=$online.LastIndexOf($needle)
  if ($pos -lt 0) { throw 'Missing makeBatches(); in mrlee-online.js. No files were changed.' }
  $pos += $needle.Length
  $online=$online.Substring(0,$pos)+(D '')+$online.Substring($pos)
}
if (-not $tracker.Contains('mrlee-review-v1')) {
  $tracker=MustReplace $tracker (D 'Y29uc3QgZGF0YSA9IGV2ZW50LmRldGFpbCB8fCB7fTs=') (D '') 'learning-tracker.js'
  $tracker=MustReplace $tracker (D 'c291cmNlOiAnY2xpZW50X3ByYWN0aWNlJywgY3JlYXRlZEF0OiBzZXJ2ZXJUaW1lc3RhbXAoKQ==') (D 'c291cmNlOiAnY2xpZW50X3ByYWN0aWNlJywgY3JlYXRlZEF0OiBzZXJ2ZXJUaW1lc3RhbXAoKSwKICAgICAgLi4uKHJldmlld0pzb24gPyB7cmV2aWV3SnNvbn0gOiB7fSk=') 'learning-tracker.js save payload'
}
if (-not $history.Contains('mrlee-review-v1')) {
  if (-not $history.Contains("from './mrlee-history-review.js'")) { $history=(D 'aW1wb3J0IHsgY3JlYXRlUmV2aWV3QWN0aW9uIH0gZnJvbSAnLi9tcmxlZS1oaXN0b3J5LXJldmlldy5qcyc7Cg==')+$history }
  $history=MustReplace $history (D 'cm93LmFwcGVuZChpbmZvLCBncmFkZSk7') (D 'cm93LmFwcGVuZChpbmZvLCBncmFkZSk7CiAgICBjcmVhdGVSZXZpZXdBY3Rpb24ocm93LCBpdGVtKTsgLy8gbXJsZWUtcmV2aWV3LXYx') 'learning-history.js'
}
# Backup ALL target files before touching them.
$folder=Join-Path $root ('BACKUP-XEM-LAI-BAI-'+(Get-Date -Format 'yyyyMMdd-HHmmss'))
New-Item -ItemType Directory -Path $folder -Force | Out-Null
foreach ($item in $required) { Copy-Item -LiteralPath (Join-Path $root $item) -Destination (Join-Path $folder $item) -ErrorAction Stop }
[System.IO.File]::WriteAllText($onlinePath,$online,$utf8)
[System.IO.File]::WriteAllText($trackerPath,$tracker,$utf8)
[System.IO.File]::WriteAllText($historyPath,$history,$utf8)
[System.IO.File]::WriteAllText((Join-Path $root 'mrlee-history-review.js'),(D ''),$utf8)
[System.IO.File]::WriteAllText((Join-Path $root 'firestore-rules-XEM-LAI-BAI-LAM.rules'),(D ''),$utf8)
Write-Host ''
Write-Host 'SUCCESS: review feature installed.' -ForegroundColor Green
Write-Host 'Backups saved to:' $folder
Write-Host 'Updated: mrlee-online.js, learning-tracker.js, learning-history.js.'
Write-Host 'Added: mrlee-history-review.js, firestore-rules-XEM-LAI-BAI-LAM.rules.'
Write-Host 'NEXT: Publish the new rules in Firebase Console > Firestore > Rules.' -ForegroundColor Yellow
Write-Host 'Then use VS Code Live Server and test a NEW online quiz, followed by the History page.'
